import React from "react";
import { IS_STATIC_SITE } from "../../../utils/staticSite";
import {
  GACHA_LOCAL_STATE_EVENT,
  GACHA_LOCAL_STATE_SYNC_KEY,
  loadGachaLocalState,
  type GachaLocalState,
} from "./gachaLocalState";

export const useGachaLocalState = () => {
  const [localState, setLocalState] = React.useState<GachaLocalState | null>(
    null,
  );

  React.useEffect(() => {
    if (!IS_STATIC_SITE) return;
    let active = true;

    const load = async () => {
      const nextState = await loadGachaLocalState();
      if (active) {
        setLocalState(nextState);
      }
    };
    let loadScheduled = false;
    const scheduleLoad = () => {
      if (loadScheduled) return;
      loadScheduled = true;
      queueMicrotask(() => {
        loadScheduled = false;
        void load();
      });
    };

    void load();

    const handleLocalStateChange = () => {
      scheduleLoad();
    };
    const handleStorage = (event: StorageEvent) => {
      if (event.key === GACHA_LOCAL_STATE_SYNC_KEY) {
        scheduleLoad();
      }
    };
    window.addEventListener(GACHA_LOCAL_STATE_EVENT, handleLocalStateChange);
    window.addEventListener("storage", handleStorage);
    return () => {
      active = false;
      window.removeEventListener(
        GACHA_LOCAL_STATE_EVENT,
        handleLocalStateChange,
      );
      window.removeEventListener("storage", handleStorage);
    };
  }, []);

  return { localState, setLocalState };
};
