import { type CasinoState } from "@hunt/frontend-client";
import type { TeamHuntState } from "@hunt/public-client";
import type { BannerDisplay, CasinoStateWithUI } from "./types";

const GACHA_ROUND_SLUG = "fates_thread_casino";

const backoutTitleFromSlug = (slug: string) =>
  slug
    .split("_")
    .map((part) => (part ? part[0].toUpperCase() + part.slice(1) : part))
    .join(" ");

export function mergeCasinoState(
  wsCasinoState: CasinoState,
  currentCasinoState: CasinoStateWithUI,
): CasinoStateWithUI {
  const isWsNewer = wsCasinoState.epoch > (currentCasinoState.epoch || 0);
  const isCurrentEmpty = !currentCasinoState.epoch;

  if (!isWsNewer && !isCurrentEmpty) {
    return currentCasinoState;
  }

  const mergedBannerProgress = [...currentCasinoState.banner_progress];

  wsCasinoState.banner_progress.forEach((wsBannerProgress) => {
    const existingIndex = mergedBannerProgress.findIndex(
      (bp) => bp.banner_slug === wsBannerProgress.banner_slug,
    );

    if (existingIndex >= 0) {
      // Update existing banner progress
      mergedBannerProgress[existingIndex] = wsBannerProgress;
    } else {
      // Add new banner progress
      mergedBannerProgress.push(wsBannerProgress);
    }
  });

  // Merge quests intelligently - only update quests that have changed
  const mergedQuests = [...(currentCasinoState.quests || [])];

  if (wsCasinoState.quests) {
    wsCasinoState.quests.forEach((wsQuest) => {
      const existingIndex = mergedQuests.findIndex(
        (q) =>
          q.quest_slug === wsQuest.quest_slug &&
          q.banner_slug === wsQuest.banner_slug,
      );

      if (existingIndex >= 0) {
        const existingQuest = mergedQuests[existingIndex];
        if (
          wsQuest.solved ||
          (wsQuest.referenced_clues && wsQuest.referenced_clues.length > 0) ||
          (wsQuest.guesses && wsQuest.guesses.length > 0)
        ) {
          mergedQuests[existingIndex] = {
            ...existingQuest, // Keep existing data as base
            ...wsQuest, // Override with websocket data
            guesses: [
              ...(wsQuest.guesses || []),
              ...(existingQuest.guesses || []),
            ], // Combine existing and new guesses
            referenced_clues: [
              ...new Set([
                ...(existingQuest.referenced_clues || []),
                ...(wsQuest.referenced_clues || []),
              ]),
            ], // Combine and deduplicate referenced clues
          };
        }
      } else {
        mergedQuests.push(wsQuest);
      }
    });
  }

  return {
    ...wsCasinoState, // Use live websocket data
    available_pulls:
      wsCasinoState.available_pulls ?? currentCasinoState.available_pulls,
    banner_progress: mergedBannerProgress,
    quests: mergedQuests,
    num_solves: wsCasinoState.num_solves ?? currentCasinoState.num_solves,
    banners: currentCasinoState.banners, // Keep original UI data for banners
    meta: currentCasinoState.meta, // Keep original UI data for meta
    banner_hints_unlocked_at: currentCasinoState.banner_hints_unlocked_at,
  };
}

export function mergeTeamStateIntoCasinoUI(
  teamState: TeamHuntState,
  currentCasinoState: CasinoStateWithUI,
): CasinoStateWithUI {
  const numFeederSolves = Object.values(teamState.puzzles).filter(
    (puzzle) =>
      puzzle.answer && puzzle.round === GACHA_ROUND_SLUG && !puzzle.is_meta,
  ).length;

  const roundSlots = teamState.rounds[GACHA_ROUND_SLUG]?.slots;

  const banners: BannerDisplay[] = currentCasinoState.banners.map((banner) => {
    const puzzle1Slug =
      roundSlots?.[banner.puzzle1.id]?.slug ?? banner.puzzle1.slug;
    const puzzle2Slug =
      roundSlots?.[banner.puzzle2.id]?.slug ?? banner.puzzle2.slug;
    const puzzle1State = puzzle1Slug
      ? teamState.puzzles[puzzle1Slug]
      : undefined;
    const puzzle2State = puzzle2Slug
      ? teamState.puzzles[puzzle2Slug]
      : undefined;

    const bannerUnlocked =
      !!puzzle1Slug &&
      !!puzzle2Slug &&
      !!puzzle1State &&
      !!puzzle2State &&
      puzzle1State.locked !== "locked" &&
      puzzle2State.locked !== "locked";

    const puzzle1Title =
      banner.puzzle1.title ??
      (puzzle1Slug ? backoutTitleFromSlug(puzzle1Slug) : undefined);
    const puzzle2Title =
      banner.puzzle2.title ??
      (puzzle2Slug ? backoutTitleFromSlug(puzzle2Slug) : undefined);

    const bannerState: BannerDisplay["state"] = bannerUnlocked
      ? "unlocked"
      : "locked";

    return {
      ...banner,
      state: bannerState,
      puzzle1: {
        ...banner.puzzle1,
        slug: puzzle1Slug ?? banner.puzzle1.slug,
        title: puzzle1Title,
        state: puzzle1State?.locked ?? banner.puzzle1.state,
        answer: puzzle1State?.answer ?? banner.puzzle1.answer,
      },
      puzzle2: {
        ...banner.puzzle2,
        slug: puzzle2Slug ?? banner.puzzle2.slug,
        title: puzzle2Title,
        state: puzzle2State?.locked ?? banner.puzzle2.state,
        answer: puzzle2State?.answer ?? banner.puzzle2.answer,
      },
    };
  });

  const metaSlug = roundSlots?.meta?.slug ?? currentCasinoState.meta?.slug;
  const metaPuzzle = metaSlug ? teamState.puzzles[metaSlug] : undefined;
  const metaTitle =
    currentCasinoState.meta?.title ??
    (metaSlug ? backoutTitleFromSlug(metaSlug) : "");
  const meta =
    metaPuzzle?.locked === "unlocked" && metaSlug
      ? {
          id: currentCasinoState.meta?.id ?? "fates_thread_casino_meta",
          title: metaTitle,
          slug: metaSlug,
          answer: metaPuzzle.answer ?? currentCasinoState.meta?.answer,
          state: metaPuzzle.locked,
        }
      : null;
  return {
    ...currentCasinoState,
    banners,
    meta,
    num_solves: numFeederSolves,
  };
}
