import { ConditionalTooltip } from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import React from "react";
import casino_chip from "../assets/casino_chip.svg";
import {
  GOLD_BUTTON_STYLING,
  GREEN_BUTTON_STYLING,
  LONG_GOLD_BUTTON_STYLING,
  RED_BUTTON_STYLING,
} from "../gacha_styling";

type Variant = "gold" | "long-gold" | "green" | "red";

type SharedProps = {
  children: React.ReactNode;
  className?: string;
  disabledMessage?: string;
  variant?: Variant;
};

function CostBadge({ cost }: { cost?: number }) {
  if (cost === undefined) return null;
  return (
    <div className="absolute -right-2 -bottom-8 bg-neutral-700 w-32 py-1 text-center pointer-events-none">
      <div className="absolute -left-7 top-1/2 -translate-y-1/2">
        <img
          src={casino_chip}
          alt="Casino Chip"
          className="w-16 h-16 select-none"
        />
      </div>
      <div className="text-white text-xl">{cost}</div>
    </div>
  );
}

export function GachaActionButton({
  className,
  children,
  cost,
  onClick,
  disabledMessage,
  variant,
}: SharedProps & {
  onClick: () => void;
  cost?: number;
}) {
  const isDisabled = disabledMessage !== undefined;

  return (
    <ConditionalTooltip tooltip={disabledMessage || undefined}>
      <div className="relative">
        <button
          className={cn(
            "w-52 py-2 text-center text-white text-2xl font-bold rounded-lg transition-all duration-200 select-none",
            "transform-gpu drop-shadow-[0_4px_4px_rgba(0,0,0,0.25)] hover:brightness-110 focus-visible:brightness-110 hover:scale-105 focus-visible:scale-105",
            isDisabled &&
              "brightness-50 hover:brightness-50 focus-visible:brightness-50 hover:scale-100 focus-visible:scale-100 cursor-not-allowed",
            variant === "gold" && GOLD_BUTTON_STYLING,
            variant === "long-gold" && LONG_GOLD_BUTTON_STYLING,
            variant === "green" && GREEN_BUTTON_STYLING,
            variant === "red" && RED_BUTTON_STYLING,
            className,
          )}
          onClick={isDisabled ? undefined : onClick}
          disabled={isDisabled}
          aria-disabled={isDisabled}
        >
          {children}
        </button>
        <CostBadge cost={cost} />
      </div>
    </ConditionalTooltip>
  );
}

type GachaActionLinkProps = SharedProps & {
  href: string;
  target?: string;
  rel?: string;
};

export function GachaActionLink({
  className,
  children,
  href,
  disabledMessage,
  target,
  rel,
  variant,
}: GachaActionLinkProps) {
  const isDisabled = disabledMessage !== undefined;

  const baseClass = cn(
    "w-52 py-2 px-4 text-center text-2xl text-white font-bold hover:text-white rounded-lg flex justify-center items-center gap-1 transition-all duration-200",
  );

  return (
    <div className="relative">
      {isDisabled ? (
        <span
          className={cn(
            baseClass,
            "brightness-50 hover:brightness-50 cursor-not-allowed pointer-events-none",
            className,
          )}
          tabIndex={-1}
          aria-disabled={true}
        >
          {children}
        </span>
      ) : (
        <a
          className={cn(
            baseClass,
            "transform-gpu drop-shadow-[0_4px_4px_rgba(0,0,0,0.25)] hover:brightness-110 focus-visible:brightness-110 hover:scale-105 focus-visible:scale-105 select-none",
            variant === "gold" && GOLD_BUTTON_STYLING,
            variant === "long-gold" && LONG_GOLD_BUTTON_STYLING,
            variant === "green" && GREEN_BUTTON_STYLING,
            variant === "red" && RED_BUTTON_STYLING,
            className,
          )}
          role="button"
          href={href}
          tabIndex={0}
          target={target}
          rel={rel}
        >
          {children}
        </a>
      )}
    </div>
  );
}
