import { erratumResourceKey, type ErratumResource } from "@hunt/public-client";
import React, { createContext, useContext } from "react";

type ErrataContextValue = {
  errataKeys: ReadonlySet<string>;
};

const ErrataContext = createContext<ErrataContextValue>({
  errataKeys: new Set<string>(),
});

export const ErrataProvider = ({
  errataKeys,
  children,
}: {
  errataKeys: ReadonlySet<string>;
  children: React.ReactNode;
}) => {
  return (
    <ErrataContext.Provider value={{ errataKeys }}>
      {children}
    </ErrataContext.Provider>
  );
};

export const useHasErratum = (
  resource: ErratumResource,
  hasErratum?: boolean,
) => {
  const { errataKeys } = useContext(ErrataContext);
  if (hasErratum !== undefined) {
    return hasErratum;
  }
  return errataKeys.has(erratumResourceKey(resource));
};
