const GACHA_LOCAL_DB_NAME = "hunt_gacha_local";
const GACHA_LOCAL_DB_VERSION = 1;
const GACHA_LOCAL_STORE = "gacha_state";
const GACHA_LOCAL_KEY = "state";

export const GACHA_LOCAL_STATE_EVENT = "hunt.gachaLocalState";
export const GACHA_LOCAL_STATE_SYNC_KEY = "hunt.gachaLocalState.sync";

type Quest = z.infer<typeof QuestSchema>;

type SerializedGachaActivityLogEntry = GachaActivityLogEntry extends infer Entry
  ? Entry extends { timestamp: Date }
    ? Omit<Entry, "timestamp"> & { timestamp: string }
    : never
  : never;

export type GachaLocalState = {
  availablePulls: number;
  bannerPullCounts: Record<string, number>;
  activityLog: SerializedGachaActivityLogEntry[];
  nextLogId: number;
  roundUnlockedAt: string;
};

type GachaLocalDb = {
  gacha_state: {
    key: string;
    value: GachaLocalState;
  };
};

const ALL_BANNER_SLUGS = Object.values(BANNERS).map((banner) => banner.slug);
const GACHA_PUZZLE_SLOTS = Object.values(PUZZLE_SLOT_TO_SLUG);

const buildDefaultBannerCounts = (): Record<string, number> => {
  return Object.fromEntries(ALL_BANNER_SLUGS.map((slug) => [slug, 0]));
};

const buildRoundUnlockedEntry = (
  timestamp: string,
): SerializedGachaActivityLogEntry => {
  return {
    id: 1,
    timestamp,
    team_id: 0,
    type: "round_unlocked",
    gacha_currency_delta: STARTING_PULLS * PULL_COST_MULTIPLIER,
  };
};

const buildDefaultLocalState = (): GachaLocalState => {
  const timestamp = new Date().toISOString();
  return {
    availablePulls: STARTING_PULLS * PULL_COST_MULTIPLIER,
    bannerPullCounts: buildDefaultBannerCounts(),
    activityLog: [buildRoundUnlockedEntry(timestamp)],
    nextLogId: 2,
    roundUnlockedAt: timestamp,
  };
};

let dbPromise: Promise<IDBPDatabase<GachaLocalDb>> | null = null;
let memoryFallbackState: GachaLocalState | null = null;

const openGachaDb = async () => {
  if (!dbPromise) {
    dbPromise = openDB<GachaLocalDb>(
      GACHA_LOCAL_DB_NAME,
      GACHA_LOCAL_DB_VERSION,
      {
        upgrade(db) {
          if (!db.objectStoreNames.contains(GACHA_LOCAL_STORE)) {
            db.createObjectStore(GACHA_LOCAL_STORE);
          }
        },
      },
    );
  }
  return dbPromise;
};

const normalizeBannerCounts = (
  counts?: Record<string, unknown> | null,
): Record<string, number> => {
  const normalized = buildDefaultBannerCounts();
  if (!counts) {
    return normalized;
  }
  Object.entries(counts).forEach(([slug, value]) => {
    if (typeof value === "number" && Number.isFinite(value)) {
      normalized[slug] = value;
    }
  });
  return normalized;
};

const normalizeActivityLog = (
  entries?: SerializedGachaActivityLogEntry[] | null,
): SerializedGachaActivityLogEntry[] => {
  if (!Array.isArray(entries)) {
    return [];
  }
  return entries.filter(
    (entry): entry is SerializedGachaActivityLogEntry =>
      Boolean(entry) &&
      typeof entry.id === "number" &&
      typeof entry.type === "string" &&
      typeof entry.timestamp === "string",
  );
};

const normalizeLocalState = (
  state?: Partial<GachaLocalState> | null,
): GachaLocalState => {
  if (!state) {
    return buildDefaultLocalState();
  }
  const bannerPullCounts = normalizeBannerCounts(
    state.bannerPullCounts ?? null,
  );
  const activityLog = normalizeActivityLog(state.activityLog ?? null);
  const availablePulls =
    typeof state.availablePulls === "number" &&
    Number.isFinite(state.availablePulls)
      ? state.availablePulls
      : STARTING_PULLS * PULL_COST_MULTIPLIER;
  const nextLogId =
    typeof state.nextLogId === "number" && Number.isFinite(state.nextLogId)
      ? Math.max(
          state.nextLogId,
          activityLog.reduce((max, entry) => Math.max(max, entry.id), 0) + 1,
        )
      : activityLog.reduce((max, entry) => Math.max(max, entry.id), 0) + 1;
  const roundUnlockedAt =
    typeof state.roundUnlockedAt === "string" && state.roundUnlockedAt.trim()
      ? state.roundUnlockedAt
      : (activityLog.find((entry) => entry.type === "round_unlocked")
          ?.timestamp ?? new Date().toISOString());

  const hasRoundUnlocked = activityLog.some(
    (entry) => entry.type === "round_unlocked",
  );
  const nextActivityLog = hasRoundUnlocked
    ? activityLog
    : [buildRoundUnlockedEntry(roundUnlockedAt), ...activityLog];

  return {
    availablePulls,
    bannerPullCounts,
    activityLog: nextActivityLog,
    nextLogId: Math.max(
      nextLogId,
      nextActivityLog.length > 0
        ? nextActivityLog.reduce((max, entry) => Math.max(max, entry.id), 0) + 1
        : 1,
    ),
    roundUnlockedAt,
  };
};

const emitLocalStateEvent = () => {
  if (typeof window === "undefined") return;
  window.dispatchEvent(new CustomEvent(GACHA_LOCAL_STATE_EVENT));
  try {
    const syncMarker = `${Date.now()}-${Math.random().toString(36).slice(2)}`;
    window.localStorage.setItem(GACHA_LOCAL_STATE_SYNC_KEY, syncMarker);
  } catch {
    // ignore localStorage errors in restricted contexts
  }
};

type GachaLocalStateMutation<T> = {
  nextState: GachaLocalState;
  result: T;
  changed: boolean;
};

const mutateGachaLocalState = async <T>(
  mutate: (state: GachaLocalState) => GachaLocalStateMutation<T>,
): Promise<GachaLocalStateMutation<T>> => {
  const mutateInMemory = (
    state: GachaLocalState,
  ): GachaLocalStateMutation<T> => {
    const mutation = mutate(state);
    const normalizedNextState = normalizeLocalState(mutation.nextState);
    if (mutation.changed) {
      memoryFallbackState = normalizedNextState;
      emitLocalStateEvent();
    } else if (!memoryFallbackState) {
      memoryFallbackState = normalizedNextState;
    }
    return {
      nextState: normalizedNextState,
      result: mutation.result,
      changed: mutation.changed,
    };
  };

  if (typeof window === "undefined") {
    const currentState = memoryFallbackState ?? buildDefaultLocalState();
    return mutateInMemory(currentState);
  }

  try {
    const db = await openGachaDb();
    const tx = db.transaction(GACHA_LOCAL_STORE, "readwrite");
    const store = tx.objectStore(GACHA_LOCAL_STORE);
    const stored = await store.get(GACHA_LOCAL_KEY);
    const currentState = normalizeLocalState(stored ?? undefined);
    const mutation = mutate(currentState);
    const normalizedNextState = normalizeLocalState(mutation.nextState);

    if (mutation.changed) {
      await store.put(normalizedNextState, GACHA_LOCAL_KEY);
    } else if (!stored) {
      await store.put(currentState, GACHA_LOCAL_KEY);
    }

    await tx.done;
    memoryFallbackState = normalizedNextState;
    if (mutation.changed) {
      emitLocalStateEvent();
    }
    return {
      nextState: normalizedNextState,
      result: mutation.result,
      changed: mutation.changed,
    };
  } catch {
    const fallbackCurrent = memoryFallbackState ?? buildDefaultLocalState();
    return mutateInMemory(fallbackCurrent);
  }
};

export const loadGachaLocalState = async (): Promise<GachaLocalState> => {
  if (typeof window === "undefined") {
    return buildDefaultLocalState();
  }
  try {
    const db = await openGachaDb();
    const stored = await db.get(GACHA_LOCAL_STORE, GACHA_LOCAL_KEY);
    const normalized = normalizeLocalState(stored ?? undefined);
    if (!stored) {
      await db.put(GACHA_LOCAL_STORE, normalized, GACHA_LOCAL_KEY);
    }
    memoryFallbackState = normalized;
    return normalized;
  } catch {
    if (!memoryFallbackState) {
      memoryFallbackState = buildDefaultLocalState();
    }
    return { ...memoryFallbackState };
  }
};

export const saveGachaLocalState = async (
  state: GachaLocalState,
): Promise<void> => {
  if (typeof window === "undefined") {
    return;
  }
  const normalized = normalizeLocalState(state);
  try {
    const db = await openGachaDb();
    await db.put(GACHA_LOCAL_STORE, normalized, GACHA_LOCAL_KEY);
    memoryFallbackState = normalized;
  } catch {
    memoryFallbackState = normalized;
  }
  emitLocalStateEvent();
};

export const resetGachaLocalState = async (): Promise<GachaLocalState> => {
  const { nextState } = await mutateGachaLocalState(() => {
    const resetState = buildDefaultLocalState();
    return {
      nextState: resetState,
      result: undefined,
      changed: true,
    };
  });
  return nextState;
};

const hydrateEntry = (
  entry: SerializedGachaActivityLogEntry,
): GachaActivityLogEntry => {
  return {
    ...entry,
    timestamp: new Date(entry.timestamp),
  } as GachaActivityLogEntry;
};

export const getHydratedGachaLog = (
  state: GachaLocalState,
): GachaActivityLogEntry[] => {
  return state.activityLog.map((entry) => hydrateEntry(entry));
};

const buildPullEntryBase = (state: GachaLocalState, timestamp: string) => ({
  team_id: 0,
  gacha_currency_delta: -1 * PULL_COST_MULTIPLIER,
  id: state.nextLogId,
  timestamp,
});

export const applyGachaPull = ({
  state,
  bannerSlug,
  numPulls,
}: {
  state: GachaLocalState;
  bannerSlug: string;
  numPulls: number;
}): {
  nextState: GachaLocalState;
  pullResults: PullBannerResult[];
  error?: string;
} => {
  if (!BANNERS[bannerSlug]) {
    return { nextState: state, pullResults: [], error: "Unknown banner." };
  }
  if (numPulls <= 0) {
    return { nextState: state, pullResults: [], error: "Invalid pull count." };
  }
  const cost = numPulls * PULL_COST_MULTIPLIER;
  if (state.availablePulls < cost) {
    return {
      nextState: state,
      pullResults: [],
      error: "You don't have enough chips.",
    };
  }

  const nextState: GachaLocalState = {
    ...state,
    bannerPullCounts: { ...state.bannerPullCounts },
    activityLog: [...state.activityLog],
    nextLogId: state.nextLogId,
  };

  let currentEventNumber = nextState.bannerPullCounts[bannerSlug] ?? 0;
  const results: PullBannerResult[] = [];
  let successfulPulls = 0;

  for (let i = 0; i < numPulls; i += 1) {
    const pull = generatePull(bannerSlug, currentEventNumber);
    if (pull.type === "error") {
      return {
        nextState: state,
        pullResults: [],
        error: pull.error_message,
      };
    }
    if (pull.type === "empty") {
      if (successfulPulls === 0) {
        return {
          nextState: state,
          pullResults: [],
          error: "This banner is empty - no more pulls available.",
        };
      }
      break;
    }

    const timestamp = new Date().toISOString();
    if (pull.type === "clue") {
      const entry: SerializedGachaActivityLogEntry = {
        ...buildPullEntryBase(nextState, timestamp),
        id: nextState.nextLogId,
        type: "clue_pulled",
        banner_slug: bannerSlug,
        puzzle_slug: pull.puzzle_slug,
        event_number: currentEventNumber,
        data: { clue_id: pull.id },
      };
      nextState.activityLog.push(entry);
      nextState.nextLogId += 1;
      results.push({
        output: {
          clue_id: TO_GACHA_UUID[pull.id],
          puzzle_slug: pull.puzzle_slug,
        },
      });
      successfulPulls += 1;
      currentEventNumber += 1;
      continue;
    }

    const entry: SerializedGachaActivityLogEntry = {
      ...buildPullEntryBase(nextState, timestamp),
      id: nextState.nextLogId,
      type: "shell_pulled",
      banner_slug: bannerSlug,
      puzzle_slug: pull.puzzle_slug,
      event_number: currentEventNumber,
    };
    nextState.activityLog.push(entry);
    nextState.nextLogId += 1;
    results.push({
      output: {
        puzzle_slug: pull.puzzle_slug,
      },
    });
    successfulPulls += 1;
    currentEventNumber += 1;
  }

  if (successfulPulls === 0) {
    return {
      nextState: state,
      pullResults: [],
      error: "This banner is empty - no more pulls available.",
    };
  }

  nextState.availablePulls = Math.max(
    0,
    nextState.availablePulls - successfulPulls * PULL_COST_MULTIPLIER,
  );
  nextState.bannerPullCounts[bannerSlug] = currentEventNumber;

  return { nextState, pullResults: results };
};

export const applyGachaPullGetAndSet = async ({
  bannerSlug,
  numPulls,
}: {
  bannerSlug: string;
  numPulls: number;
}): Promise<{
  nextState: GachaLocalState;
  pullResults: PullBannerResult[];
  error?: string;
}> => {
  const mutation = await mutateGachaLocalState((state) => {
    const result = applyGachaPull({
      state,
      bannerSlug,
      numPulls,
    });
    return {
      nextState: result.error ? state : result.nextState,
      result,
      changed: !result.error,
    };
  });

  return {
    nextState: mutation.nextState,
    pullResults: mutation.result.pullResults,
    error: mutation.result.error,
  };
};

export const addLocalPulls = (
  state: GachaLocalState,
  pullCount: number,
): GachaLocalState => {
  if (pullCount <= 0) {
    return state;
  }
  const delta = pullCount * PULL_COST_MULTIPLIER;
  const timestamp = new Date().toISOString();
  const entry: SerializedGachaActivityLogEntry = {
    id: state.nextLogId,
    timestamp,
    team_id: 0,
    type: "admin_grant",
    gacha_currency_delta: delta,
  };
  return {
    ...state,
    availablePulls: state.availablePulls + delta,
    activityLog: [...state.activityLog, entry],
    nextLogId: state.nextLogId + 1,
  };
};

export const addLocalPullsGetAndSet = async (
  pullCount: number,
): Promise<GachaLocalState> => {
  const mutation = await mutateGachaLocalState((state) => {
    const nextState = addLocalPulls(state, pullCount);
    const changed = nextState !== state;
    return {
      nextState,
      result: undefined,
      changed,
    };
  });
  return mutation.nextState;
};

const canonicalizeQuestInput = (input: string): string => {
  return input
    .trim()
    .replace(/\s+/g, " ")
    .replace(/-/g, " ")
    .normalize("NFD")
    .replaceAll(/[^\p{L}\p{N} ]/gu, "")
    .replace(/\s+/g, " ")
    .toUpperCase();
};

const QUEST_ALLOWED_INPUTS: Record<string, string[]> = {
  "meta-to-pull-or-not-to-pull": ["pull", "not pull"],
};

const checkQuestAnswers = (
  quest: { answer?: string | string[]; slug: string },
  guess: string,
  bannerSlug: string,
): { correct_answer?: string; is_valid: boolean } => {
  const answers =
    (typeof quest.answer === "string"
      ? quest.answer.split(",").map((a) => a.trim())
      : quest.answer) || [];
  const canonicalizeFn =
    bannerSlug === "hourlies" || QUEST_ALLOWED_INPUTS[quest.slug]
      ? canonicalizeQuestInput
      : canonicalizeInput;
  const canonical_input = canonicalizeFn(guess);
  const allowedInputs = QUEST_ALLOWED_INPUTS[quest.slug];
  if (allowedInputs) {
    const canonicalAllowedInputs = allowedInputs.map((answer) =>
      canonicalizeFn(answer),
    );
    if (!canonicalAllowedInputs.includes(canonical_input)) {
      return { is_valid: false };
    }
  }
  const correct_answer =
    quest.answer === "*"
      ? guess
      : answers.find((answer) => canonicalizeFn(answer) === canonical_input);

  return {
    correct_answer,
    is_valid: true,
  };
};

const getQuestsForBanner = (bannerSlug: string) => {
  const isQuest = (subpuzzle: { gacha?: { type?: string } }) =>
    subpuzzle.gacha?.type === "quest";
  if (bannerSlug === "hourlies") {
    return PUZZLES.hourlies.subpuzzles?.filter(isQuest) || [];
  }
  if (bannerSlug === "meta") {
    const metaPuzzle = PUZZLES[GACHA_META_SLUG];
    if (!metaPuzzle) return [];
    return (metaPuzzle.subpuzzles?.filter(isQuest) || []).sort((a, b) =>
      a.slug.localeCompare(b.slug),
    );
  }
  const banner = BANNERS[bannerSlug];
  if (!banner) return [];
  const leftPuzzle = banner.left_puzzle_slot
    ? PUZZLES[PUZZLE_SLOT_TO_SLUG[banner.left_puzzle_slot]]
    : undefined;
  const rightPuzzle = banner.right_puzzle_slot
    ? PUZZLES[PUZZLE_SLOT_TO_SLUG[banner.right_puzzle_slot]]
    : undefined;
  const allSubpuzzles = [
    ...(leftPuzzle?.subpuzzles || []),
    ...(rightPuzzle?.subpuzzles || []),
  ];
  return allSubpuzzles
    .filter(isQuest)
    .sort((a, b) => a.slug.localeCompare(b.slug));
};

const questGuessToGuessFormat = (
  entry: Extract<GachaActivityLogEntry, { type: "quest_guess" }>,
  submittedAnswer?: string,
) => ({
  id: entry.id,
  canonical_input: submittedAnswer ?? entry.submitted_answer,
  status: entry.guess_status,
  response: entry.gacha_currency_delta.toString(),
  timestamp: entry.timestamp.toISOString(),
});

const hourlySubmissionToGuessFormat = (
  entry: Extract<GachaActivityLogEntry, { type: "hourly_submission" }>,
) => ({
  id: entry.id,
  canonical_input: entry.submitted_answer || "",
  status: "correct" as const,
  response: entry.gacha_currency_delta.toString(),
  timestamp: entry.timestamp.toISOString(),
});

export const applyGachaQuestGuess = ({
  state,
  bannerSlug,
  questSlug,
  guess,
}: {
  state: GachaLocalState;
  bannerSlug: string;
  questSlug: string;
  guess: string;
}): {
  nextState: GachaLocalState;
  error?: string;
  canonicalInput?: string;
  solved?: boolean;
} => {
  const quests = getQuestsForBanner(bannerSlug);
  const quest = quests.find((q) => q.slug === questSlug);
  if (!quest) {
    return { nextState: state, error: "Quest not found." };
  }

  const { correct_answer, is_valid } = checkQuestAnswers(
    quest,
    guess,
    bannerSlug,
  );
  if (!is_valid) {
    return { nextState: state, error: "Invalid input." };
  }

  const hydrated = getHydratedGachaLog(state);
  const existingQuestEntries = hydrated.filter(
    (entry) =>
      "quest_slug" in entry &&
      entry.quest_slug === questSlug &&
      entry.banner_slug === bannerSlug,
  );

  const alreadySolved = existingQuestEntries.some(
    (entry) => entry.type === "quest_guess" && entry.guess_status === "correct",
  );

  const rewardPulls =
    quest.gacha?.reward_pulls ??
    (bannerSlug === "hourlies"
      ? HOURLIES_PULL_GAINS
      : KNOWLEDGE_CHECKS_PULL_GAINS);

  if (bannerSlug === "hourlies") {
    if (!correct_answer) {
      return { nextState: state, error: "Invalid input." };
    }
    const timestamp = new Date().toISOString();
    const nextState: GachaLocalState = {
      ...state,
      activityLog: [...state.activityLog],
      nextLogId: state.nextLogId,
      availablePulls: state.availablePulls,
    };

    if (!alreadySolved) {
      const rewardDelta = rewardPulls * PULL_COST_MULTIPLIER;
      nextState.activityLog.push({
        id: nextState.nextLogId,
        timestamp,
        team_id: 0,
        type: "quest_guess",
        quest_slug: questSlug,
        banner_slug: bannerSlug,
        submitted_answer: "done",
        guess_status: "correct",
        gacha_currency_delta: rewardDelta,
      });
      nextState.nextLogId += 1;
      nextState.availablePulls += rewardDelta;
    }

    nextState.activityLog.push({
      id: nextState.nextLogId,
      timestamp,
      team_id: 0,
      type: "hourly_submission",
      quest_slug: questSlug,
      banner_slug: "hourlies",
      submitted_answer: correct_answer,
      client_id: "local",
      gacha_currency_delta: 0,
    });
    nextState.nextLogId += 1;

    return {
      nextState,
      canonicalInput: correct_answer,
      solved: true,
    };
  }

  if (alreadySolved) {
    return {
      nextState: state,
      error: "Your team has already completed this quest.",
    };
  }

  const solved = Boolean(correct_answer);
  const rewardDelta = solved ? rewardPulls * PULL_COST_MULTIPLIER : 0;
  const timestamp = new Date().toISOString();

  const nextState: GachaLocalState = {
    ...state,
    activityLog: [...state.activityLog],
    nextLogId: state.nextLogId + 1,
    availablePulls: state.availablePulls + rewardDelta,
  };

  nextState.activityLog.push({
    id: state.nextLogId,
    timestamp,
    team_id: 0,
    type: "quest_guess",
    quest_slug: questSlug,
    banner_slug: bannerSlug,
    submitted_answer: correct_answer ?? guess,
    guess_status: solved ? "correct" : "incorrect",
    gacha_currency_delta: rewardDelta,
  });

  return {
    nextState,
    canonicalInput: correct_answer ?? guess,
    solved,
  };
};

export const applyGachaQuestGuessGetAndSet = async ({
  bannerSlug,
  questSlug,
  guess,
}: {
  bannerSlug: string;
  questSlug: string;
  guess: string;
}): Promise<{
  nextState: GachaLocalState;
  error?: string;
  canonicalInput?: string;
  solved?: boolean;
}> => {
  const mutation = await mutateGachaLocalState((state) => {
    const result = applyGachaQuestGuess({
      state,
      bannerSlug,
      questSlug,
      guess,
    });
    return {
      nextState: result.error ? state : result.nextState,
      result,
      changed: !result.error,
    };
  });

  return {
    nextState: mutation.nextState,
    error: mutation.result.error,
    canonicalInput: mutation.result.canonicalInput,
    solved: mutation.result.solved,
  };
};

const calculateTeamCasinoState = (
  gachaEntries: GachaActivityLogEntry[],
): {
  pulledBannerClues: Map<string, Set<string>>;
  disabledBanners: Set<string>;
} => {
  const { pulledBannerClues, pullsPerBanner } = gachaEntries.reduce(
    (
      acc: {
        pulledBannerClues: Map<string, Set<string>>;
        pullsPerBanner: Map<string, number>;
      },
      entry: GachaActivityLogEntry,
    ) => {
      if (entry.type === "clue_pulled") {
        const bannerSlug = entry.banner_slug;
        const clueId = TO_GACHA_UUID[entry.data.clue_id];
        if (entry.puzzle_slug !== GACHA_META_SLUG) {
          if (!acc.pulledBannerClues.has(bannerSlug)) {
            acc.pulledBannerClues.set(bannerSlug, new Set<string>());
          }
          acc.pulledBannerClues.get(bannerSlug)?.add(clueId);
        }
        acc.pullsPerBanner.set(
          bannerSlug,
          Math.max(acc.pullsPerBanner.get(bannerSlug) || 0, entry.event_number),
        );
      }
      return acc;
    },
    {
      pulledBannerClues: new Map<string, Set<string>>(),
      pullsPerBanner: new Map<string, number>(),
    },
  );

  const disabledBanners = new Set<string>();
  for (const [bannerSlug, pullsCount] of pullsPerBanner.entries()) {
    if (pullsCount >= DROP_META_PIECE_AT - 1) {
      disabledBanners.add(bannerSlug);
    }
  }

  return { pulledBannerClues, disabledBanners };
};

const buildBannerProgress = (
  pulledBannerClues: Map<string, Set<string>>,
  disabledBanners: Set<string>,
) => {
  return Object.entries(TOTAL_CLUES_BY_BANNER).map(
    ([bannerSlug, totalClues]) => ({
      banner_slug: BANNERS[bannerSlug].slug,
      num_clues_pulled: pulledBannerClues.get(bannerSlug)?.size || 0,
      total_clues: totalClues,
      empty: disabledBanners.has(bannerSlug),
    }),
  );
};

const getQuestStateForBanner = (
  gachaEntries: GachaActivityLogEntry[],
  bannerSlug: string,
): Quest[] => {
  const pulledClueIds = gachaEntries
    .filter((entry) => entry.type === "clue_pulled")
    .reduce((acc, entry) => {
      acc.add(entry.data.clue_id);
      return acc;
    }, new Set<string>());

  const quests = getQuestsForBanner(bannerSlug);
  return quests.map((quest) => {
    const rewardPulls =
      quest.gacha?.reward_pulls ??
      (bannerSlug === "hourlies"
        ? HOURLIES_PULL_GAINS
        : KNOWLEDGE_CHECKS_PULL_GAINS);

    const questEntries = gachaEntries.filter(
      (entry) => "quest_slug" in entry && entry.quest_slug === quest.slug,
    );

    const referencedClues: string[] = (
      quest.gacha?.referenced_clues || []
    ).filter((id) => pulledClueIds.has(id));

    if (questEntries.length === 0) {
      return {
        quest_slug: quest.slug,
        banner_slug: bannerSlug,
        guesses: [],
        referenced_clues: referencedClues,
        reward_pulls: rewardPulls,
      };
    }

    const completedEntry = questEntries.find(
      (entry) =>
        entry.type === "quest_guess" && entry.guess_status === "correct",
    ) as Extract<GachaActivityLogEntry, { type: "quest_guess" }> | undefined;
    const solved = Boolean(completedEntry);
    const answer = completedEntry?.submitted_answer;

    const guesses =
      bannerSlug === "hourlies"
        ? questEntries
            .filter((entry) => entry.type === "hourly_submission")
            .sort((a, b) => b.id - a.id)
            .map((entry) =>
              hourlySubmissionToGuessFormat(
                entry as Extract<
                  GachaActivityLogEntry,
                  { type: "hourly_submission" }
                >,
              ),
            )
        : questEntries
            .filter((entry) => entry.type === "quest_guess")
            .sort((a, b) => b.id - a.id)
            .map((entry) =>
              questGuessToGuessFormat(
                entry as Extract<
                  GachaActivityLogEntry,
                  { type: "quest_guess" }
                >,
              ),
            );

    return {
      quest_slug: quest.slug,
      banner_slug: bannerSlug,
      solved,
      answer: bannerSlug === "hourlies" ? undefined : answer,
      guesses,
      referenced_clues: referencedClues,
      reward_pulls: rewardPulls,
    };
  });
};

const getUnlockedBannerSlugs = (
  teamState: TeamHuntState,
  solvedMap: LocalSolvedPuzzleMap,
): Set<string> => {
  const solvedGachaCount = GACHA_PUZZLE_SLOTS.filter((slug) => {
    const puzzle = teamState.puzzles[slug];
    return Boolean(solvedMap[slug]) || Boolean(puzzle?.answer);
  }).length;
  const roundUnlocked =
    teamState.rounds.fates_thread_casino?.locked === "unlocked";
  const unlocked = new Set<string>();
  Object.values(BANNERS).forEach((banner) => {
    let isUnlocked = roundUnlocked;
    const condition = banner.unlockable_if;
    if ("round_unlocked" in condition) {
      isUnlocked =
        isUnlocked && condition.round_unlocked === "fates_thread_casino";
    }
    if ("puzzles_solved" in condition) {
      isUnlocked = isUnlocked && solvedGachaCount >= condition.puzzles_solved;
    }
    if (isUnlocked) {
      unlocked.add(banner.slug);
    }
  });
  return unlocked;
};

const applyLocalGachaStateToTeamState = (
  teamState: TeamHuntState,
  localState: GachaLocalState,
  solvedMap: LocalSolvedPuzzleMap,
): TeamHuntState => {
  const baseState = applySolvedMapToTeamState(teamState, solvedMap);
  const puzzles = { ...baseState.puzzles };
  const unlockedBanners = getUnlockedBannerSlugs(baseState, solvedMap);
  const hydrated = getHydratedGachaLog(localState);
  const shellPulled = new Set(
    hydrated
      .filter((entry) => entry.type === "shell_pulled")
      .map((entry) => entry.puzzle_slug),
  );
  const solvedSet = new Set(
    GACHA_PUZZLE_SLOTS.filter((slug) => {
      const puzzle = puzzles[slug];
      return Boolean(solvedMap[slug]) || Boolean(puzzle?.answer);
    }),
  );

  Object.values(BANNERS).forEach((banner) => {
    const bannerUnlocked = unlockedBanners.has(banner.slug);
    const puzzleSlugs = [
      PUZZLE_SLOT_TO_SLUG[banner.left_puzzle_slot],
      PUZZLE_SLOT_TO_SLUG[banner.right_puzzle_slot],
    ];
    puzzleSlugs.forEach((slug) => {
      const puzzle = puzzles[slug];
      if (!puzzle) return;
      const isSolved = solvedSet.has(slug);
      const hasShell = shellPulled.has(slug);
      const lockedState: GachaPuzzle["state"] =
        isSolved || hasShell
          ? "unlocked"
          : bannerUnlocked
            ? "unlockable"
            : "locked";
      puzzles[slug] = {
        ...puzzle,
        locked: lockedState,
      };
    });
  });

  const metaPuzzle = puzzles[GACHA_META_SLUG];
  if (metaPuzzle) {
    const solvedCount = solvedSet.size;
    const metaUnlocked = solvedCount >= 7;
    puzzles[GACHA_META_SLUG] = {
      ...metaPuzzle,
      locked: metaUnlocked ? "unlocked" : "locked",
    };
  }

  return {
    ...baseState,
    puzzles,
  };
};

export const buildLocalTeamState = ({
  teamState,
  localState,
  solvedMap,
}: {
  teamState: TeamHuntState;
  localState: GachaLocalState;
  solvedMap: LocalSolvedPuzzleMap;
}): TeamHuntState => {
  return applyLocalGachaStateToTeamState(teamState, localState, solvedMap);
};

export const buildLocalCasinoState = ({
  teamState,
  localState,
  solvedMap,
}: {
  teamState: TeamHuntState;
  localState: GachaLocalState;
  solvedMap: LocalSolvedPuzzleMap;
}): CasinoStateWithUI => {
  const hydrated = getHydratedGachaLog(localState);
  const { pulledBannerClues, disabledBanners } =
    calculateTeamCasinoState(hydrated);
  const banner_progress = buildBannerProgress(
    pulledBannerClues,
    disabledBanners,
  );
  const unlockedBanners = Array.from(
    getUnlockedBannerSlugs(teamState, solvedMap),
  );
  const questBanners = [...unlockedBanners, "hourlies"];
  const quests = questBanners.flatMap((bannerSlug) =>
    getQuestStateForBanner(hydrated, bannerSlug),
  );

  const patchedTeamState = applyLocalGachaStateToTeamState(
    teamState,
    localState,
    solvedMap,
  );
  const casinoState = {
    epoch: Date.now(),
    available_pulls: localState.availablePulls,
    banner_progress,
    quests,
    num_solves: GACHA_PUZZLE_SLOTS.filter((slug) => {
      const puzzle = patchedTeamState.puzzles[slug];
      return Boolean(solvedMap[slug]) || Boolean(puzzle?.answer);
    }).length,
  };
  return casinoUIState(patchedTeamState, casinoState);
};

export const buildLocalPullHistoryEvents = (
  localState: GachaLocalState,
): (CluePullEvent | ShellPullEvent)[] => {
  const hydrated = getHydratedGachaLog(localState);
  return hydrated
    .flatMap((entry) => {
      if (entry.type === "clue_pulled") {
        const type =
          entry.puzzle_slug === GACHA_META_SLUG ? "meta_clue" : "clue";
        return {
          type,
          bannerSlug: entry.banner_slug,
          timestamp: entry.timestamp.toISOString(),
          clueId: TO_GACHA_UUID[entry.data.clue_id],
          eventNumber: entry.event_number,
        } as CluePullEvent;
      }
      if (entry.type === "shell_pulled") {
        return {
          type: "shell",
          bannerSlug: entry.banner_slug,
          timestamp: entry.timestamp.toISOString(),
          puzzleSlug: entry.puzzle_slug,
          puzzleTitle: PUZZLES[entry.puzzle_slug]?.title || "",
          eventNumber: entry.event_number,
        } as ShellPullEvent;
      }
      return [];
    })
    .sort((a, b) => a.eventNumber - b.eventNumber);
};

export const buildLocalGalleryClues = (
  localState: GachaLocalState,
): { clue_id: string; banner_slug: string }[] => {
  const hydrated = getHydratedGachaLog(localState);
  const uniqueClues = new Map<
    string,
    { clue_id: string; banner_slug: string; first_pull_time: Date }
  >();

  hydrated.forEach((entry) => {
    if (entry.type !== "clue_pulled") return;
    if (entry.puzzle_slug === GACHA_META_SLUG) return;
    const uuid = TO_GACHA_UUID[entry.data.clue_id];
    if (!uniqueClues.has(uuid)) {
      uniqueClues.set(uuid, {
        clue_id: uuid,
        banner_slug: entry.banner_slug,
        first_pull_time: entry.timestamp,
      });
    }
  });

  return Array.from(uniqueClues.values())
    .sort((a, b) => a.first_pull_time.getTime() - b.first_pull_time.getTime())
    .map(({ clue_id, banner_slug }) => ({ clue_id, banner_slug }));
};
