function genBanners(
  teamState: TeamHuntState,
  roundSlug: string,
  slotToBannerData: Record<GachaBannerSlot, PuzzleRecord | GachaBannerRecord>,
): BannerDisplay[] {
  const round = teamState.rounds[roundSlug];
  if (!round) return [];

  const banners: BannerDisplay[] = [];

  for (const bannerSlot of Object.keys(
    slotToBannerData,
  ) as _GACHA_BANNER_SLOTS[]) {
    const data = slotToBannerData[bannerSlot];

    if (!("puzzle1" in data) || !("puzzle2" in data)) {
      continue;
    }

    const bannerData = data as GachaBannerRecord;
    const slug1 = lookupSlug(bannerData.puzzle1.id, teamState, roundSlug);
    const slug2 = lookupSlug(bannerData.puzzle2.id, teamState, roundSlug);
    const puzzleState1 = slug1 ? teamState.puzzles[slug1] : undefined;
    const puzzleState2 = slug2 ? teamState.puzzles[slug2] : undefined;

    if (
      slug1 === undefined ||
      slug2 === undefined ||
      puzzleState1 === undefined ||
      puzzleState2 === undefined ||
      puzzleState1.locked === "locked" ||
      puzzleState2.locked === "locked"
    ) {
      const bannerDisplay: BannerDisplay = {
        slug: bannerData.slug,
        asset_grayscale: bannerData.asset_grayscale,
        asset_color: bannerData.asset_color,
        sidebar_asset:
          bannerData.locked_sidebar_asset ?? bannerData.sidebar_asset,
        sidebar_asset_grayscale: bannerData.sidebar_asset_grayscale,
        name: bannerData.name,
        alt: bannerData.alt,
        state: "locked",
        glow_color: bannerData.glow_color,
        puzzle1: {
          id: bannerData.puzzle1.id,
          shell_image_color: bannerData.puzzle1.shell_image_color,
          shell_image_grayscale: bannerData.puzzle1.shell_image_grayscale,
          tooltip_position: bannerData.puzzle1.tooltip_position,
          state: "locked",
        },
        puzzle2: {
          id: bannerData.puzzle2.id,
          shell_image_color: bannerData.puzzle2.shell_image_color,
          shell_image_grayscale: bannerData.puzzle2.shell_image_grayscale,
          tooltip_position: bannerData.puzzle2.tooltip_position,
          state: "locked",
        },
        layers_color: bannerData.layers_color,
        layers_grayscale: bannerData.layers_grayscale,
      };

      banners.push(bannerDisplay);
    } else {
      const puzzle1 = PUZZLES[slug1];
      const puzzle2 = PUZZLES[slug2];
      const title1 = puzzle1
        ? getPuzzleTitle(puzzle1, teamState)
        : getStubTitle(slug1 || "", false);
      const title2 = puzzle2
        ? getPuzzleTitle(puzzle2, teamState)
        : getStubTitle(slug2 || "", false);

      const bannerDisplay: BannerDisplay = {
        slug: bannerData.slug,
        asset_grayscale: bannerData.asset_grayscale,
        asset_color: bannerData.asset_color,
        sidebar_asset: bannerData.sidebar_asset,
        sidebar_asset_grayscale: bannerData.sidebar_asset_grayscale,
        name: bannerData.name,
        alt: bannerData.alt,
        glow_color: bannerData.glow_color,
        // Banners don't have an "unlockable" state.
        state: "unlocked",
        puzzle1: {
          id: bannerData.puzzle1.id,
          title: title1,
          slug: slug1,
          answer: puzzleState1.answer,
          state: puzzleState1.locked,
          nsfw: puzzle1?.content.nsfw,
          shell_image_color: bannerData.puzzle1.shell_image_color,
          shell_image_grayscale: bannerData.puzzle1.shell_image_grayscale,
          tooltip_position: bannerData.puzzle1.tooltip_position,
        },
        puzzle2: {
          id: bannerData.puzzle2.id,
          title: title2,
          slug: slug2,
          answer: puzzleState2.answer,
          state: puzzleState2.locked,
          nsfw: puzzle2?.content.nsfw,
          shell_image_color: bannerData.puzzle2.shell_image_color,
          shell_image_grayscale: bannerData.puzzle2.shell_image_grayscale,
          tooltip_position: bannerData.puzzle2.tooltip_position,
        },
        layers_color: bannerData.layers_color,
        layers_grayscale: bannerData.layers_grayscale,
      };

      banners.push(bannerDisplay);
    }
  }

  return banners;
}

export function casinoUIState(
  teamState: TeamHuntState,
  casinoState?: CasinoState,
): CasinoStateWithUI {
  const casinoStateData =
    casinoState ||
    (() => {
      const numGachaSolves = Object.values(teamState.puzzles).filter(
        (puzzle) => puzzle.answer && puzzle.round === "fates_thread_casino",
      ).length;

      return {
        epoch: Date.now(),
        num_solves: numGachaSolves,
        banner_progress: [],
      };
    })();

  const banners = genBanners(
    teamState,
    "fates_thread_casino",
    SLOT_TO_BANNER_DATA,
  );

  const metaSlug = teamState.rounds.fates_thread_casino.slots.meta?.slug;
  const meta = metaSlug ? PUZZLES[metaSlug] : null;
  const metaTitle = meta ? getPuzzleTitle(meta, teamState) : "";
  const metaState = metaSlug ? teamState.puzzles[metaSlug] : undefined;

  return {
    ...casinoStateData,
    banners,
    meta:
      metaState?.locked === "unlocked"
        ? {
            id: "fates_thread_casino_meta",
            title: metaTitle,
            slug: metaSlug,
            answer: metaState?.answer || "",
            state: metaState?.locked,
          }
        : null,
  };
}

const UNLOCKED_SIDEBAR_ASSETS_BY_SLUG: Record<
  string,
  { sidebar_asset: string; sidebar_asset_grayscale: string }
> = Object.values(SLOT_TO_BANNER_DATA).reduce<
  Record<string, { sidebar_asset: string; sidebar_asset_grayscale: string }>
>((acc, data) => {
  if (!("puzzle1" in data) || !("puzzle2" in data)) {
    return acc;
  }
  const bannerData = data as GachaBannerRecord;
  acc[bannerData.slug] = {
    sidebar_asset: bannerData.sidebar_asset,
    sidebar_asset_grayscale: bannerData.sidebar_asset_grayscale,
  };
  return acc;
}, {});

export const buildUnlockAllBannerDisplay = ({
  teamState,
  banners,
}: {
  teamState: TeamHuntState;
  banners: BannerDisplay[];
}): BannerDisplay[] => {
  const hydratePuzzle = (
    slotId: string,
    puzzle: BannerDisplay["puzzle1"],
  ): BannerDisplay["puzzle1"] => {
    const slug = lookupSlug(slotId, teamState, "fates_thread_casino");
    if (!slug) {
      return { ...puzzle, state: "unlocked" };
    }
    const puzzleData = PUZZLES[slug];
    return {
      ...puzzle,
      slug,
      title: puzzleData ? getPuzzleTitle(puzzleData, teamState) : puzzle.title,
      answer: teamState.puzzles[slug]?.answer ?? puzzle.answer,
      nsfw: puzzleData?.content.nsfw,
      state: "unlocked",
    };
  };

  return banners.map((banner) => ({
    ...banner,
    ...(UNLOCKED_SIDEBAR_ASSETS_BY_SLUG[banner.slug] ?? {}),
    state: "unlocked",
    puzzle1: hydratePuzzle(banner.puzzle1.id, banner.puzzle1),
    puzzle2: hydratePuzzle(banner.puzzle2.id, banner.puzzle2),
  }));
};

export const buildUnlockAllMetaDisplay = ({
  teamState,
  currentMeta,
}: {
  teamState: TeamHuntState;
  currentMeta: GachaPuzzle | null;
}): GachaPuzzle | null => {
  if (currentMeta) {
    return currentMeta;
  }
  const metaSlug = teamState.rounds.fates_thread_casino.slots.meta?.slug;
  if (!metaSlug) {
    return null;
  }
  const metaPuzzle = PUZZLES[metaSlug];
  if (!metaPuzzle) {
    return null;
  }
  return {
    id: "fates_thread_casino_meta",
    slug: metaSlug,
    title: getPuzzleTitle(metaPuzzle, teamState),
    answer: teamState.puzzles[metaSlug]?.answer ?? "",
    state: "unlocked",
  };
};
